document.querySelectorAll('.discover-toggle').forEach(b=>{const menu=b.closest('.discover-menu');b.onclick=()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));menu.classList.toggle('is-open',open)};menu.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.classList.remove('is-open');b.setAttribute('aria-expanded','false');b.focus()}});document.addEventListener('click',e=>{if(!menu.contains(e.target)){menu.classList.remove('is-open');b.setAttribute('aria-expanded','false')}})});